@pytest.mark.parametrize("case", CASES, ids=[c["id"] for c in CASES])
def test_module_interfaces(run, workdir, case):
    """CATCHES: an imported type, record field, constructor, pattern, effect or unit that
    resolves, checks, lowers or reports differently from the reference."""
    S.check(run, workdir, case, __file__)
